NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Zechariah'

CHAPTERS = {
    1: {
        1: 'V osmem mesecu, v drugem letu Dareja, je prišla Gospodova beseda Zahariju, Berehjájevemu sinu, Idójevemu sinu, preroku, rekoč:',
        2: '» Gospod je bil ogorčeno nezadovoljen z vašimi očeti.',
        3: 'Zato jim reci: ›Tako govori Gospod nad bojevniki: ›Obrnite se k meni,‹ govori Gospod nad bojevniki ›in jaz se bom obrnil k vam,‹ govori Gospod nad bojevniki.',
        4: '›Ne bodite kakor vaši očetje, h katerim so klicali prejšnji preroki, rekoč: ›Tako govori Gospod nad bojevniki: ›Obrnite se sedaj iz svojih zlih poti in od svojih zlih početij,‹ toda niso poslušali niti mi niso prisluhnili,‹ govori Gospod.',
        5: '›Vaši očetje, kje so? In preroki, mar večno živijo?',
        6: 'Toda mar se moje besede in moji zakoni, ki sem jih zapovedal svojim služabnikom prerokom niso prijeli vaših očetov? In pokesali so se ter rekli: ›Kakor nam je Gospod nad bojevniki mislil storiti, glede na naše poti in glede na naša početja, tako je postopal z nami.‹«',
        7: 'Na štiriindvajseti dan enajstega meseca, ki je mesec šebát, v drugem letu kralja Dareja, je prišla Gospodova beseda Zahariju, Berehjájevemu sinu, Idójevemu sinu, preroku, rekoč:',
        8: '»Videl sem ponoči in glej moža, jahajočega na rdečem konju in stal je med mirtinimi drevesi, ki so bila na dnu in za njimi so bili rdeči konji, lisasti in beli.«',
        9: 'Potem sem rekel: »Oh moj gospod, kdo so ti?« Angel, ki je govoril z menoj, mi je rekel: »Pokazal ti bom kdo so ti.«',
        10: 'Mož, ki je stal med mirtinimi drevesi, je odgovoril in rekel: »To so tisti, ki jih je Gospod poslal, da hodijo sem ter tja po zemlji.«',
        11: 'Odgovorili so Gospodovemu angelu, ki je stal med mirtinimi drevesi in rekli: »Hodili smo sem ter tja po zemlji in glej, vsa zemlja mirno sedi in je pri počitku.«',
        12: 'Potem je Gospodov angel odgovoril in rekel: »Oh Gospod nad bojevniki, doklej ne boš imel usmiljenja nad Jeruzalemom in nad Judovimi mesti, zoper katere si imel ogorčenje teh sedemdeset let?«',
        13: 'Gospod je odgovoril angelu, ki je govoril z menoj, z dobrimi besedami in tolažilnimi besedami.',
        14: 'Tako mi je angel, ki je govoril z menoj, rekel: »Kliči, rekoč: ›Tako govori Gospod nad bojevniki: ›Ljubosumen sem zaradi Jeruzalema in zaradi Siona z velikim ljubosumjem.',
        15: 'Silno sem ogorčeno nezadovoljen s pogani, ki so oholi, kajti bil sem le malo nezadovoljen, oni pa so pomagali, da je stiska napredovala.‹«',
        16: 'Zato tako govori Gospod: »Z usmiljenji sem se vrnil k Jeruzalemu. Moja hiša bo zgrajena v njem,« govori Gospod nad bojevniki »in [merilna] vrvica bo raztegnjena nad Jeruzalemom.',
        17: 'Še kliči, rekoč: ›Tako govori Gospod nad bojevniki: ›Moja mesta bodo prek blaginje še razširjena naokoli, in Gospod bo še potolažil Sion in bo še izbral Jeruzalem.‹«',
        18: 'Potem sem povzdignil svoje oči in videl in glej, štirje rogovi.',
        19: 'Rekel sem angelu, ki je govoril z menoj: »Kaj so tile?« Odgovoril mi je: »Ti so rogovi, ki so razkropili Juda, Izraela in Jeruzalem.',
        20: 'Gospod mi je pokazal štiri tesarje.',
        21: 'Potem sem rekel: »Kaj so ti prišli delat?« Spregovoril je, rekoč: »Ti so rogovi, ki so razkropili Juda, tako da noben človek ni vzdignil svoje glave, toda prišli so, da jih prestrašijo, da odbijejo rogove poganov, ki so svoje rogove povzdignili nad Judovo deželo, da jo razkropijo.«',
    },
    2: {
        1: 'Ponovno sem povzdignil svoje oči in pogledal in glej, mož z merilno vrvico v svoji roki.',
        2: 'Potem sem rekel: »Kam greš?« Rekel mi je: »Da izmerim Jeruzalem, da vidim kakšna je njegova širina in kakšna je njegova dolžina.«',
        3: 'Glej, angel, ki je govoril z menoj, je šel naprej in drug angel je odšel ven, da ga sreča',
        4: 'ter mu rekel: »Teci, govori temu mladeniču, rekoč: › [Prestolnica] Jeruzalem bo naseljena kakor mesta brez zidov, zaradi množice ljudi in živine v njej.‹',
        5: 'Kajti jaz,« govori Gospod, »ji bom ognjen zid vsenaokrog in bom slava v njeni sredi.',
        6: 'Hej, hej, pridite in pobegnite iz severne dežele,« govori Gospod, »kajti razkropil sem vas naokrog kakor štiri vetrove neba,« govori Gospod.',
        7: '»Osvobodi se, oh Sion, ki prebivaš z babilonsko hčerjo.«',
        8: 'Kajti tako govori Gospod nad bojevniki: »Za slavo me je poslal k narodom, ki so vas plenili. Kajti kdor se dotakne vas, se dotakne punčice njegovega očesa.',
        9: 'Kajti glej, svojo roko bom stresel nad njimi in postali bodo plen svojim služabnikom in vedeli boste, da me je poslal Gospod nad bojevniki.',
        10: 'Prepevaj in razveseljuj se, oh hči sionska, kajti glej, prihajam in prebival bom v tvoji sredi,« govori Gospod.',
        11: '»Na tisti dan bodo številni narodi pridruženi h Gospodu in bodo moje ljudstvo in jaz bom prebival v tvoji sredi in vedela boš, da me je Gospod nad bojevniki poslal k tebi.',
        12: 'Gospod bo podedoval Juda in njegov delež v sveti deželi in ponovno bo izbral Jeruzalem.',
        13: 'Molči, oh vse meso, pred Gospodom, kajti vzdignjen je iz svojega svetega prebivališča.«',
    },
    3: {
        1: 'Pokazal mi je Ješúa, vélikega duhovnika, stati pred Gospodovim angelom in Satana, stoječega na njegovi desnici, da se mu upira.',
        2: 'Gospod je rekel Satanu: » Gospod te oštej, oh Satan. Celó Gospod, ki je izbral Jeruzalem, naj te ošteje. Mar ni to ogorek, potegnjen iz ognja?«',
        3: 'Torej Ješúa je bil oblečen v umazane obleke in stal pred angelom.',
        4: 'Odgovoril je in spregovoril tistim, ki so stali pred njim, rekoč: »Odvzemite umazane obleke z njega.« Rekel mu je: »Glej, tvoji krivičnosti sem velel, da gre od tebe in oblekel te bom z zamenjavo oblačil.«',
        5: 'Rekel sem: »Naj na njegovo glavo postavijo lep turban.« Tako so na njegovo glavo postavili lep turban in ga oblekli z oblekami. In Gospodov angel je stal poleg.',
        6: 'Gospodov angel je izpričal Ješúu, rekoč:',
        7: '»Tako govori Gospod nad bojevniki: ›Če se boš ravnal po mojih poteh in če se boš držal moje zadolžitve, potem boš sodil tudi mojo hišo in se boš držal mojih dvorov in dal ti bom prostore za hojo med tistimi, ki stojijo poleg.',
        8: 'Poslušaj sedaj, oh Ješúa, véliki duhovnik, ti in tvoji tovariši, ki sedijo pred teboj, kajti oni so ljudje čudenja. Kajti, glej, privedel bom svojega služabnika MLADIKO.',
        9: 'Kajti poglej, kamen, ki sem ga položil pred Ješúa. Na enem kamnu bo sedem oči. Glej, vrezal bom graviranje le-tega,« govori Gospod nad bojevniki »in krivičnost te dežele bom odstranil v enem dnevu.',
        10: 'Na ta dan,« govori Gospod nad bojevniki, »boste vabili vsakdo svojega soseda pod trto in pod figovo drevo.«',
    },
    4: {
        1: 'Angel, ki je govoril z menoj, je ponovno prišel in me prebudil, kakor človeka, ki je prebujen iz svojega spanja',
        2: 'ter mi rekel: »Kaj vidiš?« Rekel sem: »Pogledal sem in glej, svečnik, ves iz zlata, s skledico na njegovem vrhu in njegovih sedem svetilk na njem in sedem cevk k sedmim svetilkam, ki so na njegovem vrhu.',
        3: 'In ob njem dve oljki, eno na desni strani skledice in drugo na njeni levi strani.«',
        4: 'Tako sem odgovoril in spregovoril angelu, ki je govoril z menoj, rekoč: »Kaj so ti, moj gospod?«',
        5: 'Potem je angel, ki je govoril z menoj, odgovoril in mi rekel: »Ali ne veš kaj so ti?« Rekel sem: »Ne, moj gospod.«',
        6: 'Potem je odgovoril in mi spregovoril, rekoč: »To je beseda od Gospoda Zerubabélu, rekoč: ›Ne z močjo niti ne z oblastjo, temveč z mojim duhom,‹« govori Gospod nad bojevniki.',
        7: '›Kdo si ti, oh velika gora? Pred Zerubabélom boš postala ravnina in on bo privedel njen zaključni kamen z vriskanji, kličoč: ›Milost, milost njemu.‹«',
        8: 'Poleg tega je prišla k meni Gospodova beseda, rekoč:',
        9: '»Zerubabélove roke so položile temelj tej hiši. Njegove roke jo bodo tudi dokončale in vedel boš, da me je k vam poslal Gospod nad bojevniki.',
        10: 'Kajti kdo je preziral dan majhnih stvari? Kajti razveseljevali se bodo in videli grezilo v roki Zerubabéla s tistimi sedmimi. Te so Gospodove oči, ki tečejo sem ter tja po celotni zemlji.«',
        11: 'Potem sem odgovoril in mu rekel: »Kaj sta ti dve oljki na desni strani svečnika in na njegovi levi strani?«',
        12: 'Ponovno sem odgovoril in mu rekel: »Kaj sta ti dve oljkovi mladiki, ki skozi dve zlati cevki praznita zlato olje iz njiju.«',
        13: 'Odgovoril mi je in rekel: »Ne veš kaj sta le-ti? Rekel sem: »Ne, moj gospod.«',
        14: 'Potem je rekel: »To sta dva maziljenca, ki stojita pri Gospodu celotne zemlje.«',
    },
    5: {
        1: 'Potem sem se obrnil, povzdignil svoje oči, pogledal in zagledal leteči zvitek.',
        2: 'Rekel mi je: »Kaj vidiš?« Odgovoril sem: »Vidim leteči zvitek. Njegova dolžina je dvajset komolcev in njegova širina deset komolcev.«',
        3: 'Potem mi je rekel: »To je prekletstvo, ki gre naprej preko obličja celotne zemlje, kajti vsak, kdor krade, bo pokončan kakor na tej strani, glede na to; in vsak, kdor prisega, bo pokončan kakor na tisti strani, glede na to.«',
        4: '»Privedel ga bom naprej,« govori Gospod nad bojevniki »in ta bo vstopil v hišo tatu in v hišo tistega, ki krivo prisega pri mojem imenu. In ta bo ostal v sredi njegove hiše in použil jo bo z njenim lesom in njenimi kamni.«',
        5: 'Potem je angel, ki je govoril z menoj, odšel naprej in mi rekel: »Dvigni sedaj svoje oči in poglej kaj je to, kar gre naprej.«',
        6: 'Rekel sem: »Kaj je to?« Rekel je: »To je škaf, ki gre naprej.« Poleg tega je rekel: »To je njihov videz po vsej zemlji.«',
        7: 'Glej, tam je bil dvignjen talent iz svinca in to je ženska, ki sedi na sredi škafa.',
        8: 'Rekel je: »To je zlobnost.« In vrgel jo je na sredo škafa in svinčeno utež je vrgel na njegovo odprtino.',
        9: 'Potem sem povzdignil svoje oči in pogledal in glej, tam sta prišli ven dve ženski in veter je bil v njunih perutih, kajti peruti sta imeli podobni perutim štorklje in škaf sta dvignili med zemljo in nebo.',
        10: 'Potem sem rekel angelu, ki je govoril z menoj: »Kam ti [dve] nosita škaf?«',
        11: 'Rekel mi je: »Da mu zgradijo hišo v deželi Šinár. In ta bo utrjena in tam ga postavita na njegov lastni temelj.«',
    },
    6: {
        1: 'Obrnil sem se, povzdignil svoje oči, pogledal in glej, prišli so štirje vozovi izmed dveh gora in gori sta bili gori iz brona.',
        2: 'Pri prvem vozu so bili rdeči konji, pri drugem vozu črni konji,',
        3: 'pri tretjem vozu beli konji in pri četrtem vozu osiveli in rjavi konji.',
        4: 'Potem sem odgovoril in rekel angelu, ki je govoril z menoj: »Kaj so ti, moj gospod?«',
        5: 'Angel je odgovoril in mi rekel: »To so štirje nebeški duhovi, ki gredo naprej, [potem ko so stali] pred Gospodom vse zemlje.«',
        6: 'Črni konji, ki so pri njem, gredo v severno deželo. Beli gredo za njimi in osiveli gredo proti južni deželi.',
        7: 'Rjavci pa so šli naprej in iskali, da bi lahko hodili sem ter tja po zemlji. Rekel je: »Pojdite od tod, hodite sem ter tja po zemlji.« Tako so hodili sem ter tja po zemlji.',
        8: 'Potem mi je zaklical in mi spregovoril, rekoč: »Poglej, ti, ki gredo proti severni deželi, so utišali mojega duha v severni deželi.«',
        9: 'K meni je prišla Gospodova beseda, rekoč:',
        10: '»Vzemi od teh iz ujetništva, torej od Heldája, od Tobija in od Jedajája, ki so prišli iz Babilona in pridi isti dan in pojdi v hišo Cefanjájevega sina Jošíja.',
        11: 'Potem vzemi srebro in zlato in naredi krone in jih postavi na glavo Ješúa, Jocadákovega sina, vélikega duhovnika',
        12: 'in mu spregovori, rekoč: ›Tako govori Gospod nad bojevniki, rekoč: ›Glej, mož, katerega ime je MLADIKA; in rastel bo iz svojega kraja in zgradil bo Gospodov tempelj.',
        13: 'Celo on bo zgradil Gospodov tempelj in nosil bo slavo in sedel bo in vladal na svojem prestolu in bo duhovnik na svojem prestolu in namera miru bo med obema.‹«',
        14: 'Krone bodo Helému, Tobiju, Jedajáju in Cefanjájevemu sinu Henu v spomin, v Gospodovem templju.',
        15: 'Tisti, ki so daleč proč, bodo prišli in gradili v Gospodovem templju in vedeli boste, da me je Gospod nad bojevniki poslal k vam. In to se bo zgodilo, če boste marljivo ubogali glas Gospoda, svojega Boga.',
    },
    7: {
        1: 'Pripetilo se je v četrtem letu kralja Dareja, da je Gospodova beseda prišla Zahariju na četrti dan devetega meseca, torej v kislévu,',
        2: 'ko so poslali v Božjo hišo Sarécerja in Regem Meleha in njune može, da molijo pred Gospodom',
        3: 'in da govorijo duhovnikom, ki so bili v hiši Gospoda nad bojevniki in prerokom, rekoč: »Ali naj bi jokal v petem mesecu in se zadrževal, kot sem to počel ta mnoga leta?«',
        4: 'Potem je prišla k meni beseda Gospoda nad bojevniki, rekoč:',
        5: '»Govori vsemu ljudstvu dežele in duhovnikom, rekoč: ›Ko ste se postili in žalovali v petem in sedmem mesecu, celo teh sedemdeset let, ali ste se sploh postili meni, celó zame?',
        6: 'In ko ste jedli in ko ste pili, mar niste jedli zase in pili zase?',
        7: 'Mar naj ne bi slišali besed, ki jih je Gospod klical po prejšnjih prerokih, ko je bil Jeruzalem naseljen in v uspevanju in njegova mesta okoli njega, ko so ljudje naseljevali jug in ravnino?‹«',
        8: 'Gospodova beseda je prišla Zahariju, rekoč:',
        9: '»Tako govori Gospod nad bojevniki, rekoč: ›Izvajajte resnično sodbo in izkazujte usmiljenje in sočutja vsakdo svojemu bratu,',
        10: 'in ne stiskajte vdove, niti osirotelega, niti tujca, niti revnega, in naj si nihče izmed vas v svojem srcu ne domišlja zla zoper svojega brata.',
        11: 'Toda zavrnili so, da bi prisluhnili in odmaknili so ramo in si zamašili svoja ušesa, da ne bi slišali.',
        12: 'Da, svoja srca so naredili kakor diamantni kamen, da ne bi slišali postave in besed, ki jih je Gospod nad bojevniki poslal po svojem duhu po prejšnjih prerokih, zato je prišel velik bes od Gospoda nad bojevniki.',
        13: 'Zato se je zgodilo, da kakor je on klical in niso hoteli slišati, tako so klicali in nisem hotel slišati,« govori Gospod nad bojevniki,',
        14: '»temveč sem jih z vrtinčastim vetrom razkropil med vse narode, ki jih niso poznali. Tako je bila dežela za njimi zapuščena, da noben človek ni šel skoznjo niti se ni vrnil, kajti prijetno deželo so spremenili v opustošeno.«',
    },
    8: {
        1: 'Ponovno je prišla k meni beseda Gospoda nad bojevniki, rekoč:',
        2: '»Tako govori Gospod nad bojevniki: ›Z velikim ljubosumjem sem bil ljubosumen zaradi Siona in zaradi njega sem bil ljubosumen s silno razjarjenostjo.‹',
        3: 'Tako govori Gospod: ›Vrnem se k Sionu in prebival bom v sredi Jeruzalema in Jeruzalem bo imenovan mesto resnice in gora Gospoda nad bojevniki sveta gora.‹',
        4: 'Tako govori Gospod nad bojevniki: ›Še bodo starci in starke prebivali na ulicah Jeruzalema in vsak mož s svojo palico v svoji roki zaradi visoke starosti.',
        5: 'Ulice mesta bodo polne fantov in deklet, ki se bodo igrali na ulicah le-tega.‹',
        6: 'Tako govori Gospod nad bojevniki: ›Če je to čudovito v očeh preostanka tega ljudstva v tistih dneh, mar ne bi bilo čudovito tudi v mojih očeh?‹ govori Gospod nad bojevniki.',
        7: 'Tako govori Gospod nad bojevniki: ›Glej, rešil bom svoje ljudstvo iz vzhodne dežele in iz zahodne dežele',
        8: 'in privedel jih bom in prebivali bodo v sredi Jeruzalema. In oni bodo moje ljudstvo in jaz bom njihov Bog v resnici in v pravičnosti.‹',
        9: 'Tako govori Gospod nad bojevniki: ›Naj bodo vaše roke močne, vi, ki v teh dneh slišite te besede po ustih prerokov, ki so bili na dan, ko je bil položen temelj hiše Gospoda nad bojevniki, da bi bil tempelj lahko zgrajen.',
        10: 'Kajti pred temi dnevi ni bilo plačila za moža niti kateregakoli plačila za žival; niti zaradi stiske ni bilo nobenega miru tistemu, ki je odhajal ali prihajal, kajti vse ljudi sem naravnal, vsakega zoper svojega soseda.',
        11: 'Toda sedaj preostanku tega ljudstva ne bom kakor v prejšnjih dneh,‹ govori Gospod nad bojevniki.',
        12: '›Kajti seme bo uspešno; trta bo dajala svoj sad in tla bodo dajala svoj prirastek in nebo bo dajalo svojo roso. In preostanku tega ljudstva bom povzročil, da vzamejo v last vse te stvari.',
        13: 'In zgodilo se bo, da kakor ste bili prekletstvo med pogani, oh hiša Judova in hiša Izraelova, tako vas bom rešil in boste blagoslov. Ne bojte se, temveč naj bodo vaše roke močne.',
        14: 'Kajti tako govori Gospod nad bojevniki: ›Kakor sem vas mislil kaznovati, ko so me vaši očetje dražili do besa,‹ govori Gospod nad bojevniki in se nisem pokesal,',
        15: 'tako sem v teh dneh ponovno mislil, da storim dobro Jeruzalemu in Judovi hiši. Ne bojte se.',
        16: 'To so stvari, ki jih boste storili: ›Govorite vsak človek resnico svojemu sosedu; izvršujte sodbo resnice in miru v svojih velikih vratih',
        17: 'in naj si nihče izmed vas v svojih srcih ne domišlja zla zoper svojega soseda in ne ljubite krive prisege, kajti vse to so stvari, ki jih sovražim,‹ govori Gospod.«',
        18: 'Prišla mi je beseda Gospoda nad bojevniki, rekoč:',
        19: '»Tako govori Gospod nad bojevniki: ›Post četrtega meseca, post petega, post sedmega in post desetega bo Judovi hiši radost in veselje in vedre gostije, zato ljubite resnico in mir.‹',
        20: 'Tako govori Gospod nad bojevniki: ›Še se bo zgodilo, da bodo prihajala ljudstva in prebivalci mnogih mest',
        21: 'in prebivalci enega mesta bodo šli k drugemu, rekoč: ›Pojdimo naglo, da molimo pred Gospodom in da iščemo Gospoda nad bojevniki.‹ ›Tudi jaz bom šel.‹«',
        22: 'Da, številna ljudstva in močni narodi bodo prišli, da iščejo Gospoda nad bojevniki v Jeruzalemu in da molijo pred Gospodom.',
        23: 'Tako govori Gospod nad bojevniki: »V tistih dneh se bo zgodilo, da bo deset mož iz vseh jezikov narodov prijelo tistega, ki je Jud in celo prijelo krajec njegovega oblačila, rekoč: ›Šli bomo s teboj, kajti slišali smo, da je z vami Bog.‹«',
    },
    9: {
        1: '§ »Breme Gospodove besede v deželi Hadráh in Damask bo njegov počitek, ko bodo oči človeka kakor od vseh Izraelovih rodov, [usmerjene] proti Gospodu.',
        2: 'Tudi Hamát bo njegova meja, Tir in Sidón, čeprav je ta zelo moder.',
        3: '[Naselbina] Tir si je zgradila oporišče in nakopičila srebra kakor prahu in čistega zlata kakor uličnega blata.',
        4: 'Glej, Gospod jo bo vrgel ven in udaril bo njeno oblast na morju in použita bo z ognjem.',
        5: 'Aškelón bo to videl in se bo bal. Tudi Gaza bo to videla in bo zelo žalostna in Ekrón, kajti njegovo pričakovanje bo osramočeno in kralj bo odtaval iz Gaze in Aškelón ne bo naseljen.',
        6: 'Mešanec bo prebival v Ašdódu in jaz bom iztrebil ponos Filistejcev.',
        7: 'Njegovo kri bom odvzel iz njegovih ust in njegove ogabnosti izmed njegovih zob. Toda kdor ostaja, celo on, bo za našega Boga in bo kakor voditelj v Judu in Ekrón bo kakor Jebusejec.',
        8: 'Utaboril se bom okrog svoje hiše zaradi vojske, zaradi tistega, ki gre mimo in zaradi tistega, ki se vrača. Noben zatiralec ne bo več šel skoznje, kajti sedaj sem videl s svojimi očmi.',
        9: 'Silno se veseli, oh sionska hči. Vriskaj, oh jeruzalemska hči. Glej, tvoj Kralj prihaja k tebi; pravičen je in ima rešitev duše; ponižen in jahajoč na oslu in žrebetu, osličjem žrebetu.',
        10: 'Iztrebil bom voz iz Efrájima, konja iz Jeruzalema in bojni lok bo odrezan in govoril bo mir poganom. Njegovo gospostvo bo od morja celó do morja in od reke celó do koncev zemlje.',
        11: 'Tudi kar se tebe tiče, s krvjo tvoje zaveze sem tvoje jetnike poslal iz jame, v kateri ni vode.',
        12: 'Obrnite se k oporišču, vi jetniki upanja. Celo danes razglašam, da ti bom povrnil dvojno;',
        13: 'ko sem si ukrivil Juda, lok napolnil z Efrájimom in vzdignil tvoje sinove, oh Sion, zoper tvoje sinove, oh Grčija in te naredil kakor meč mogočnega človeka.«',
        14: 'Gospod bo viden nad njimi in njegova puščica bo šla naprej kakor bliskanje in Gospod Bog bo zatrobil na šofar in pojde z južnimi vrtinčastimi vetrovi.',
        15: 'Gospod nad bojevniki jih bo branil in požrli bodo in podjarmili s kamni [iz] prače, in pili bodo in naredili hrup kakor od vina; in napolnjeni bodo kakor skledice in kakor oltarni vogali.',
        16: 'Gospod, njihov Bog, jih bo na tisti dan rešil, kakor trop svojega ljudstva, kajti oni bodo kakor kamni krone, povzdignjeni kakor zastava nad njegovo deželo.',
        17: 'Kajti kako velika je njegova dobrota in kako velika je njegova lepota! Žito bo mladeniče naredilo radostne in novo vino mladenke.',
    },
    10: {
        1: 'Zahtevajte od Gospoda dež v času poznejšega dežja. Tako bo Gospod naredil svetle oblake in jim dal nalive dežja, vsaki travi na polju.',
        2: 'Kajti maliki so govorili ničevost, vedeževalci so videli laž in povedali napačne sanje. Zaman tolažijo. Zatorej so odšli po svoji poti kakor trop, zaskrbljeni so bili, ker ni bilo pastirja.',
        3: 'Moja jeza je bila vžgana zoper pastirje in kaznoval sem kozle, kajti Gospod nad bojevniki je obiskal svoj trop, Judovo hišo in jih naredil kakor odličnega konja v bitki.',
        4: '§ Iz njega bo prišel vogal, iz njega klin, iz njega bojni lok, iz njega tudi vsak zatiralec.',
        5: 'Oni bodo kakor mogočni ljudje, ki v bitki pomendrajo svoje sovražnike v uličnem blatu in borili se bodo, ker je Gospod z njimi in jezdeci na konjih bodo zbegani.',
        6: 'Okrepil bom Judovo hišo in rešil Jožefovo hišo in ponovno jih bom privedel, da jih namestim, kajti usmiljenje imam nad njimi in oni bodo, kakor jih ne bi zavrgel, kajti jaz sem Gospod, njihov Bog in uslišal jih bom.',
        7: 'Tisti iz Efrájima bodo podobni mogočnemu človeku in njihovo srce se bo veselilo kakor zaradi vina. Da, njihovi otroci bodo to videli in bodo veseli; njihovo srce se bo veselilo v Gospodu.',
        8: '»Požvižgal jim bom in jih zbral, ker sem jih odkupil in narasli bodo, kakor so oni narasli.',
        9: 'Sejal jih bom med ljudstvom in spomnili se me bodo v daljnih deželah in živeli bodo s svojimi otroki in se ponovno vrnili.',
        10: 'Ponovno jih bom privedel tudi iz egiptovske dežele in jih zbral iz Asirije. Privedel jih bom v deželo Gileád in Libanon in ne bo najti prostora zanje.',
        11: 'S stisko bo prešel skozi morje in udaril bo valove v morju in vse globine reke se bodo posušile. Ponos Asirije bo ponižan in egiptovsko žezlo bo odšlo proč.',
        12: 'Okrepil jih bom v Gospodu in hodili bodo gor in dol v njegovem imenu,« govori Gospod.',
    },
    11: {
        1: 'Odpri svoja vrata, oh Libanon, da bo ogenj lahko pogoltnil tvoje cedre.',
        2: 'Tuli cipresa, kajti cedra je padla, ker so mogočni oplenjeni. Tulite, oh vi, bašánski hrasti, kajti neprehoden gozd je posekan.',
        3: 'Tam je glas tuljenja pastirjev, kajti njihova slava je oplenjena. Glas rjovenja mladih levov, kajti ponos Jordana je oplenjen.',
        4: 'Tako govori Gospod, moj Bog: »Hrani trop za zakol,',
        5: 'katerih lastniki jih ubijajo in se nimajo za krive; in tisti, ki jih prodajajo, pravijo: ›Blagoslovljen bodi Gospod, kajti bogat sem,‹ in njihovi lastni pastirji jim ne prizanašajo.',
        6: 'Kajti ne bom več prizanašal prebivalcem dežele,‹ govori Gospod, ›temveč glej, izročil bom ljudi, vsakega v roko njegovega soseda in v roko njegovega kralja in udarili bodo deželo in iz njihove roke jih ne bom osvobodil.',
        7: 'Jaz bom pasel trop za zakol, celó vas, oh ubogi izmed tropa. Vzel sem si dve palici. Eno sem imenoval Lepota, drugo pa sem imenoval Vezi; in jaz sem pasel trop.',
        8: 'Tudi tri pastirje uničim v enem mesecu in moji duši so se gnusili in tudi njihova duša je zaničevala mene.',
        9: 'Potem sem rekel: ›Ne bom vas pasel. Tisti, ki umira, naj umre in tisti, ki naj bi bil uničen, naj bo ta uničen, preostali pa naj jedo vsakdo meso drugega.',
        10: 'Vzel sem svojo palico, celó Lepoto in jo zlomil, da bi lahko prelomil svojo zavezo, ki sem jo sklenil z vsem ljudstvom.',
        11: 'Ta je bila prelomljena na tisti dan.‹« In tako so ubogi iz tropa, ki so čakali name, vedeli, da je bila to Gospodova beseda.',
        12: 'Rekel sem jim: »Če mislite dobro, mi dajte moje plačilo, in če ne, opustite.« Tako so odtehtali za moje plačilo trideset koščkov srebra.',
        13: 'Gospod mi je rekel: »Vrzi to lončarju. Lepo plačilo, za katero so me ovrednotili.« Vzel sem trideset koščkov srebra in jih vrgel v Gospodovo hišo, k lončarju.',
        14: 'Potem sem zlomil svojo drugo palico, celó Vezi, da bi lahko prelomil bratstvo med Judom in Izraelom.',
        15: 'Gospod mi je rekel: »K sebi vzemi še priprave nespametnega pastirja.',
        16: 'Kajti glej, vzdignil bom pastirja v deželi, ki ne bo obiskoval tistih, ki so uničeni niti ne bo iskal mladih niti zdravil tega, kar je zlomljeno niti pasel tega, kar stoji mirno, temveč bo jedel meso rejenega in njihove parklje trgal na koščke.',
        17: 'Gorje malikovalskemu pastirju, ki zapušča čredo! Meč bo nad njegovim laktom in nad njegovim desnim očesom. Njegov laket bo popolnoma osušen in njegovo desno oko bo skrajno otemnelo.«',
    },
    12: {
        1: '»Breme o Gospodovi besedi za Izrael,« govori Gospod, ki razprostira nebo in polaga temelj zemlji in oblikuje človeškega duha znotraj njega.',
        2: '»Glej, Jeruzalem bom naredil čašo trepetanja vsemu ljudstvu naokoli, ko bodo v obleganju tako zoper Juda in zoper Jeruzalem.',
        3: 'Na tisti dan bom naredil [prestolnico] Jeruzalem obremenilni kamen za vse ljudstvo. Vsi, ki se bremenijo s tem, bodo razsekani na koščke, čeprav bo vse ljudstvo zemlje zbrano zoper njo.',
        4: 'Na tisti dan,« govori Gospod, »bom vsakega konja udaril z osuplostjo in njegovega jezdeca z norostjo in svoje oči bom odprl nad Judovo hišo in vsakega konja ljudstva bom udaril s slepoto.',
        5: 'Voditelji Juda bodo v svojem srcu rekli: ›Prebivalci Jeruzalema bodo moja moč v Gospodu nad bojevniki, njihovem Bogu.‹',
        6: 'Na tisti dan bom naredil voditelje Juda kakor ognjeno ognjišče med lesom in ognjeno baklo v snopu in použili bodo vse ljudstvo naokoli, na desni roki in na levi in Jeruzalem bo ponovno naseljen na svojem lastnem kraju, celó v Jeruzalemu.',
        7: 'Gospod bo tudi najprej rešil Judove šotore, da se slava Davidove hiše in slava prebivalcev Jeruzalema ne bo poveličevala zoper Juda.',
        8: 'Na tisti dan bo Gospod branil prebivalce Jeruzalema. Kdor bo na tisti dan med njimi slaboten, bo kakor David in Davidova hiša bo kakor Bog, kakor Gospodov angel pred njimi.',
        9: 'In zgodilo se bo na tisti dan, da si bom prizadeval uničiti vse narode, ki pridejo zoper Jeruzalem.',
        10: 'Na Davidovo hišo in na prebivalce Jeruzalema bom izlil duha milosti in ponižnih prošenj in gledali bodo name, ki so ga prebodli in žalovali bodo za njim, kakor nekdo žaluje za svojim edinim sinom in v grenkobi bodo za njim, kakor nekdo, ki je v grenkobi zaradi svojega prvorojenca.',
        11: 'Na tisti dan bo v Jeruzalemu veliko žalovanje, kakor žalovanje za Hadád Rimónom v dolini Megído.',
        12: 'Dežela bo žalovala, vsaka družina posebej; družina Davidove hiše posebej in njihove žene posebej, družina Natánove hiše posebej in njihove žene posebej,',
        13: 'družina Lévijeve hiše posebej in njihove žene posebej, Šimíjeva družina posebej in njihove žene posebej.',
        14: 'Vse družine, ki preostanejo, vsaka družina posebej in njihove žene posebej.«',
    },
    13: {
        1: '»Na tisti dan bo studenec odprt Davidovi hiši in prebivalcem Jeruzalema zaradi greha in zaradi nečistosti.',
        2: 'In zgodilo se bo na tisti dan,« govori Gospod nad bojevniki, » da bom iz dežele iztrebil imena malikov in ne bodo se jih več spominjali, in prav tako bom prerokom in nečistemu duhu povzročil, da zapustijo deželo.',
        3: 'In zgodilo se bo, da kdorkoli bo še prerokoval, potem mu bosta njegov oče in njegova mati, ki sta ga zaplodila, rekla: ›Ne boš živel, kajti v Gospodovem imenu govoriš laži.‹ Njegov oče in njegova mati, ki sta ga zaplodila, ga bosta prebodla, ko prerokuje.',
        4: 'Na tisti dan se bo zgodilo, da bodo preroki osramočeni, vsak zaradi svoje vizije, ko je prerokoval. Niti ne bodo nosili grobe obleke, da bi zavajali,',
        5: 'temveč bo rekel: ›Jaz nisem prerok, poljedelec sem. Kajti mož me je od moje mladosti naučil, da varujem živino.‹',
        6: 'In nekdo mu bo rekel: ›Kaj so te rane na tvojih rokah?‹ Potem bo odgovoril: › Tiste, s katerimi sem bil ranjen v hiši svojih prijateljev.‹',
        7: 'Prebudi se, oh meč, zoper mojega pastirja in zoper človeka, ki je moj družabnik,« govori Gospod nad bojevniki, »udari pastirja in ovce bodo razkropljene in svojo roko bom [ponovno] obrnil nad malčke.',
        8: 'In zgodilo se bo, da bosta v vsej tej deželi,« govori Gospod, »dva njena dela odsekana in bosta umrla, toda tretji bo ostal v njej.',
        9: 'In tretji del bom popeljal skozi ogenj in prečistil jih bom, kakor se prečiščuje srebro in preizkusil jih bom, kakor se preizkuša zlato. Klicali bodo k mojemu imenu in jaz jih bom slišal: ›Rekel bom: ›To je moje ljudstvo‹ in rekli bodo: » Gospod je moj Bog.‹«',
    },
    14: {
        1: '»Poglej, dan Gospodov prihaja in tvoj plen bo razdeljen v tvoji sredi.',
        2: 'Kajti vse narode bom zbral, da se borijo zoper Jeruzalem. Mesto bo zavzeto, hiše oplenjene in ženske posiljene. Polovica mesta bo odšla v ujetništvo, preostanek ljudstva pa ne bo iztrebljen iz mesta.«',
        3: 'Takrat bo prišel Gospod in se boril zoper te narode, kakor ko se je boril na dan bitke.',
        4: 'Na tisti dan bodo njegova stopala stopila na Oljsko goro, ki je na vzhodu, pred Jeruzalemom in Oljska gora se bo razklala po sredi proti vzhodu in proti zahodu in tam bo zelo velika dolina. Polovica gore bo odstranjena proti severu, polovica pa proti jugu.',
        5: 'Bežali boste k dolini [med] gorama, kajti dolina [med] gorama bo segala do Azela. Da, bežali boste, podobno kakor ste bežali pred potresom v dneh Judovega kralja Uzíjaha. In Gospod, moj Bog, bo prišel in vsi sveti [bodo] s teboj.',
        6: '§ In zgodilo se bo na tisti dan, da svetloba ne bo razločna, niti tema,',
        7: 'temveč bo en dan, ki bo poznan Gospodu, niti dan, niti noč, temveč se bo zgodilo, da bo ob večernem času svetloba.',
        8: 'In to bo na tisti dan, da bodo žive vode izšle iz Jeruzalema. Polovica izmed njih proti prvemu morju in polovica proti zadnjemu morju. To bo poleti in pozimi.',
        9: 'In Gospod bo kralj nad vso zemljo. Na tisti dan bo en Gospod in njegovo ime eno.',
        10: 'Vsa dežela bo narejena kakor ravnina od Gebe do Rimóna, južno od Jeruzalema, in ta bo dvignjen in naseljen na svojem kraju, od Benjaminovih velikih vrat, do mesta prvih velikih vrat, do Vogalnih velikih vrat in od Hananélovega stolpa do kraljevih vinskih stiskalnic.',
        11: 'V njem bodo prebivali ljudje in tam ne bo več skrajnega uničenja, temveč bo Jeruzalem varno naseljen.',
        12: 'To pa bo kuga, s katero bo Gospod udaril vsa ljudstva, ki so se borila zoper Jeruzalem. Njihovo meso bo zgnilo, medtem ko stojijo na svojih stopalih in njihove oči bodo zgnile v njihovih jamicah in njihov jezik bo zgnil v njihovih ustih.',
        13: 'Na tisti dan se bo zgodilo, da bo med njimi velika zmešnjava od Gospoda, in vsakdo bo zgrabil roko svojega soseda in svojo roko bo vzdignil zoper roko svojega soseda.',
        14: 'Tudi Juda se bo bojeval v Jeruzalemu in premoženje vseh poganov naokoli se bo zbralo skupaj, zlata, srebra in oblačil v velikem obilju.',
        15: 'Kakor ta kuga, takšna bo kuga konja, mule, kamele, osla in vseh živali, ki bodo v teh šotoriščih.',
        16: 'Zgodilo se bo, da kdor preostane izmed vseh narodov, ki so prišli zoper Jeruzalem, bo torej hodil gor iz leta v leto, da obožuje kralja, Gospoda nad bojevniki in da praznuje šotorski praznik.',
        17: 'In zgodilo se bo, da kdorkoli, izmed vseh družin zemlje, ne bo prišel gor v Jeruzalem, da obožuje Kralja, Gospoda nad bojevniki, celo nad njim ne bo dežja.',
        18: 'In če družina iz Egipta ne gre gor in ne pride, da tam ni dežja, bo tam kuga, s katero bo Gospod udaril pogane, ki ne pridejo gor, da praznujejo šotorski praznik.',
        19: 'To bo kazen Egiptu in kazen vsem narodom, ki ne pridejo gor, da praznujejo šotorski praznik.',
        20: 'Na tisti dan bo na konjskih zvončkih SVETO Gospodu in lonci v Gospodovi hiši bodo podobni skledicam pred oltarjem.',
        21: 'Da, vsak lonec v Jeruzalemu in v Judeji bo svetost Gospodu nad bojevniki. Vsi tisti, ki žrtvujejo, bodo prišli in jemali iz njih in kuhali v njih. Na tisti dan ne bo več Kánaancev v hiši Gospoda nad bojevniki.',
    },
}
